300→fn serialization_failure_outcome(hook_events: Vec<HookCompletedEvent>) -> StopOutcome {
301→    StopOutcome {
302→        hook_events,
303→        should_stop: false,
304→        stop_reason: None,
305→        should_block: false,
306→        block_reason: None,
307→        continuation_fragments: Vec::new(),
308→    }
309→}
