 28→#[derive(Clone)]
 29→pub struct Hooks {
 30→    after_agent: Vec<Hook>,
 31→    after_tool_use: Vec<Hook>,
 32→    engine: ClaudeHooksEngine,
 33→}
 34→
 35→impl Default for Hooks {
 36→    fn default() -> Self {
 37→        Self::new(HooksConfig::default())
 38→    }
 39→}
 40→
 41→impl Hooks {
 42→    pub fn new(config: HooksConfig) -> Self {
 43→        let after_agent = config
 44→            .legacy_notify_argv
 45→            .filter(|argv| !argv.is_empty() && !argv[0].is_empty())
 46→            .map(crate::notify_hook)
 47→            .into_iter()
 48→            .collect();
 49→        let engine = ClaudeHooksEngine::new(
 50→            config.feature_enabled,
 51→            config.config_layer_stack.as_ref(),
 52→            CommandShell {
 53→                program: config.shell_program.unwrap_or_default(),
 54→                args: config.shell_args,
 55→            },
 56→        );
 57→        Self {
 58→            after_agent,
 59→            after_tool_use: Vec::new(),
 60→            engine,
 61→        }
 62→    }
 63→
 64→    pub fn startup_warnings(&self) -> &[String] {
 65→        self.engine.warnings()
 66→    }
 67→
 68→    fn hooks_for_event(&self, hook_event: &HookEvent) -> &[Hook] {
 69→        match hook_event {
 70→            HookEvent::AfterAgent { .. } => &self.after_agent,
 71→            HookEvent::AfterToolUse { .. } => &self.after_tool_use,
 72→        }
 73→    }
 74→
 75→    pub async fn dispatch(&self, hook_payload: HookPayload) -> Vec<HookResponse> {
 76→        let hooks = self.hooks_for_event(&hook_payload.hook_event);
 77→        let mut outcomes = Vec::with_capacity(hooks.len());
 78→        for hook in hooks {
 79→            let outcome = hook.execute(&hook_payload).await;
 80→            let should_abort_operation = outcome.result.should_abort_operation();
 81→            outcomes.push(outcome);
 82→            if should_abort_operation {
 83→                break;
 84→            }
 85→        }
 86→
 87→        outcomes
 88→    }
 89→
