 39→fn write_stop_hook(home: &Path, block_prompts: &[&str]) -> Result<()> {
 40→    let script_path = home.join("stop_hook.py");
 41→    let log_path = home.join("stop_hook_log.jsonl");
 42→    let prompts_json =
 43→        serde_json::to_string(block_prompts).context("serialize stop hook prompts for test")?;
 44→    let script = format!(
 45→        r#"import json
 46→from pathlib import Path
 47→import sys
 48→
 49→log_path = Path(r"{log_path}")
 50→block_prompts = {prompts_json}
 51→
 52→payload = json.load(sys.stdin)
 53→existing = []
 54→if log_path.exists():
 55→    existing = [line for line in log_path.read_text(encoding="utf-8").splitlines() if line.strip()]
 56→
 57→with log_path.open("a", encoding="utf-8") as handle:
 58→    handle.write(json.dumps(payload) + "\n")
 59→
 60→invocation_index = len(existing)
 61→if invocation_index < len(block_prompts):
 62→    print(json.dumps({{"decision": "block", "reason": block_prompts[invocation_index]}}))
 63→else:
 64→    print(json.dumps({{"systemMessage": f"stop hook pass {{invocation_index + 1}} complete"}}))
 65→"#,
 66→        log_path = log_path.display(),
 67→        prompts_json = prompts_json,
 68→    );
 69→    let hooks = serde_json::json!({
 70→        "hooks": {
 71→            "Stop": [{
 72→                "hooks": [{
 73→                    "type": "command",
 74→                    "command": format!("python3 {}", script_path.display()),
 75→                    "statusMessage": "running stop hook",
 76→                }]
 77→            }]
 78→        }
 79→    });
 80→
 81→    fs::write(&script_path, script).context("write stop hook script")?;
 82→    fs::write(home.join("hooks.json"), hooks.to_string()).context("write hooks.json")?;
 83→    Ok(())
 84→}
