 13→#[derive(Debug)]
 14→pub(crate) struct CommandRunResult {
 15→    pub started_at: i64,
 16→    pub completed_at: i64,
 17→    pub duration_ms: i64,
 18→    pub exit_code: Option<i32>,
 19→    pub stdout: String,
 20→    pub stderr: String,
 21→    pub error: Option<String>,
 22→}
 23→
 24→pub(crate) async fn run_command(
 25→    shell: &CommandShell,
 26→    handler: &ConfiguredHandler,
 27→    input_json: &str,
 28→    cwd: &Path,
 29→) -> CommandRunResult {
 30→    let started_at = chrono::Utc::now().timestamp();
 31→    let started = Instant::now();
 32→
 33→    let mut command = build_command(shell, handler);
 34→    command
 35→        .current_dir(cwd)
 36→        .stdin(Stdio::piped())
 37→        .stdout(Stdio::piped())
 38→        .stderr(Stdio::piped())
 39→        .kill_on_drop(true);
 40→
 41→    let mut child = match command.spawn() {
 42→        Ok(child) => child,
 43→        Err(err) => {
 44→            return CommandRunResult {
 45→                started_at,
 46→                completed_at: chrono::Utc::now().timestamp(),
 47→                duration_ms: started.elapsed().as_millis().try_into().unwrap_or(i64::MAX),
 48→                exit_code: None,
 49→                stdout: String::new(),
 50→                stderr: String::new(),
 51→                error: Some(err.to_string()),
 52→            };
 53→        }
 54→    };
 55→
 56→    if let Some(mut stdin) = child.stdin.take()
 57→        && let Err(err) = stdin.write_all(input_json.as_bytes()).await
 58→    {
 59→        let _ = child.kill().await;
 60→        return CommandRunResult {
 61→            started_at,
 62→            completed_at: chrono::Utc::now().timestamp(),
 63→            duration_ms: started.elapsed().as_millis().try_into().unwrap_or(i64::MAX),
 64→            exit_code: None,
 65→            stdout: String::new(),
 66→            stderr: String::new(),
 67→            error: Some(format!("failed to write hook stdin: {err}")),
 68→        };
 69→    }
 70→
 71→    let timeout_duration = Duration::from_secs(handler.timeout_sec);
 72→    match timeout(timeout_duration, child.wait_with_output()).await {
 73→        Ok(Ok(output)) => CommandRunResult {
 74→            started_at,
 75→            completed_at: chrono::Utc::now().timestamp(),
 76→            duration_ms: started.elapsed().as_millis().try_into().unwrap_or(i64::MAX),
 77→            exit_code: output.status.code(),
 78→            stdout: String::from_utf8_lossy(&output.stdout).to_string(),
 79→            stderr: String::from_utf8_lossy(&output.stderr).to_string(),
 80→            error: None,
 81→        },
 82→        Ok(Err(err)) => CommandRunResult {
 83→            started_at,
 84→            completed_at: chrono::Utc::now().timestamp(),
 85→            duration_ms: started.elapsed().as_millis().try_into().unwrap_or(i64::MAX),
 86→            exit_code: None,
 87→            stdout: String::new(),
 88→            stderr: String::new(),
 89→            error: Some(err.to_string()),
 90→        },
 91→        Err(_) => CommandRunResult {
 92→            started_at,
 93→            completed_at: chrono::Utc::now().timestamp(),
 94→            duration_ms: started.elapsed().as_millis().try_into().unwrap_or(i64::MAX),
 95→            exit_code: None,
 96→            stdout: String::new(),
 97→            stderr: String::new(),
 98→            error: Some(format!("hook timed out after {}s", handler.timeout_sec)),
 99→        },
100→    }
101→}
