 59→pub(crate) fn parse_pre_tool_use(stdout: &str) -> Option<PreToolUseOutput> {
 60→    let PreToolUseCommandOutputWire {
 61→        universal: universal_wire,
 62→        decision,
 63→        reason,
 64→        hook_specific_output,
 65→    } = parse_json(stdout)?;
 66→    let universal = UniversalOutput::from(universal_wire);
 67→    let hook_specific_output = hook_specific_output.as_ref();
 68→    let use_hook_specific_decision = hook_specific_output.is_some_and(|output| {
 69→        output.permission_decision.is_some()
 70→            || output.permission_decision_reason.is_some()
 71→            || output.updated_input.is_some()
 72→            || output.additional_context.is_some()
 73→    });
 74→    let invalid_reason = unsupported_pre_tool_use_universal(&universal).or_else(|| {
 75→        if use_hook_specific_decision {
 76→            hook_specific_output.and_then(unsupported_pre_tool_use_hook_specific_output)
 77→        } else {
 78→            unsupported_pre_tool_use_legacy_decision(decision.as_ref(), reason.as_deref())
 79→        }
 80→    });
 81→    let block_reason = if invalid_reason.is_none() {
 82→        if use_hook_specific_decision {
 83→            hook_specific_output.and_then(|output| match output.permission_decision {
 84→                Some(PreToolUsePermissionDecisionWire::Deny) => output
 85→                    .permission_decision_reason
 86→                    .as_deref()
 87→                    .and_then(trimmed_reason),
 88→                _ => None,
 89→            })
 90→        } else {
 91→            match decision.as_ref() {
 92→                Some(PreToolUseDecisionWire::Block) => reason.as_deref().and_then(trimmed_reason),
 93→                Some(PreToolUseDecisionWire::Approve) | None => None,
 94→            }
 95→        }
 96→    } else {
 97→        None
 98→    };
 99→
100→    Some(PreToolUseOutput {
101→        universal,
102→        block_reason,
103→        invalid_reason,
104→    })
105→}
