255→    /// Account-facing plan classification derived from the current token.
256→    /// Returns a high-level `AccountPlanType` (e.g., Free/Plus/Pro/Team/…)
257→    /// mapped from the ID token's internal plan value. Prefer this when you
258→    /// need to make UI or product decisions based on the user's subscription.
259→    /// When ChatGPT auth is active but the token omits the plan claim, report
260→    /// `Unknown` instead of treating the account as invalid.
261→    pub fn account_plan_type(&self) -> Option<AccountPlanType> {
262→        let map_known = |kp: &InternalKnownPlan| match kp {
263→            InternalKnownPlan::Free => AccountPlanType::Free,
264→            InternalKnownPlan::Go => AccountPlanType::Go,
265→            InternalKnownPlan::Plus => AccountPlanType::Plus,
266→            InternalKnownPlan::Pro => AccountPlanType::Pro,
267→            InternalKnownPlan::Team => AccountPlanType::Team,
268→            InternalKnownPlan::Business => AccountPlanType::Business,
269→            InternalKnownPlan::Enterprise => AccountPlanType::Enterprise,
270→            InternalKnownPlan::Edu => AccountPlanType::Edu,
271→        };
272→
273→        self.get_current_token_data().map(|t| {
274→            t.id_token
275→                .chatgpt_plan_type
276→                .map(|pt| match pt {
277→                    InternalPlanType::Known(k) => map_known(&k),
278→                    InternalPlanType::Unknown(_) => AccountPlanType::Unknown,
279→                })
280→                .unwrap_or(AccountPlanType::Unknown)
281→        })
282→    }
