215→// acceptTrustDialogIfNeeded checks whether the workspace trust dialog appears
216→// and presses "a" to accept it. The dialog only shows on the first launch in
217→// a workspace — subsequent sessions in the same directory skip it.
218→func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
219→	// Race: either the trust dialog or the input prompt will appear first.
220→	// Use a short timeout to check for the trust dialog without blocking
221→	// too long if the workspace is already trusted.
222→	content, err := s.WaitFor(`Trust this workspace|`+a.PromptPattern(), 30*time.Second)
223→	if err != nil {
224→		return fmt.Errorf("waiting for trust dialog or prompt: %w", err)
225→	}
226→	if strings.Contains(content, "Trust this workspace") {
227→		if err := s.SendKeys("a"); err != nil {
228→			return fmt.Errorf("accepting trust dialog: %w", err)
229→		}
230→	}
231→	return nil
232→}
