  1→//! CLI login commands and their direct-user observability surfaces.
  2→//!
  3→//! The TUI path already installs a broader tracing stack with feedback, OpenTelemetry, and other
  4→//! interactive-session layers. Direct `codex login` intentionally does less: it preserves the
  5→//! existing stderr/browser UX and adds only a small file-backed tracing layer for login-specific
  6→//! targets. Keeping that setup local avoids pulling the TUI's session-oriented logging machinery
  7→//! into a one-shot CLI command while still producing a durable `codex-login.log` artifact that
  8→//! support can request from users.
  9→
 10→use codex_core::CodexAuth;
 11→use codex_core::auth::AuthCredentialsStoreMode;
 12→use codex_core::auth::AuthMode;
 13→use codex_core::auth::CLIENT_ID;
 14→use codex_core::auth::login_with_api_key;
 15→use codex_core::auth::logout;
 16→use codex_core::config::Config;
 17→use codex_login::ServerOptions;
 18→use codex_login::run_device_code_login;
 19→use codex_login::run_login_server;
 20→use codex_protocol::config_types::ForcedLoginMethod;
 21→use codex_utils_cli::CliConfigOverrides;
 22→use std::fs::OpenOptions;
 23→use std::io::IsTerminal;
 24→use std::io::Read;
 25→use std::path::PathBuf;
 26→use tracing_appender::non_blocking;
 27→use tracing_appender::non_blocking::WorkerGuard;
 28→use tracing_subscriber::EnvFilter;
 29→use tracing_subscriber::Layer;
 30→use tracing_subscriber::layer::SubscriberExt;
 31→use tracing_subscriber::util::SubscriberInitExt;
 32→
 33→const CHATGPT_LOGIN_DISABLED_MESSAGE: &str =
 34→    "ChatGPT login is disabled. Use API key login instead.";
 35→const API_KEY_LOGIN_DISABLED_MESSAGE: &str =
 36→    "API key login is disabled. Use ChatGPT login instead.";
 37→const LOGIN_SUCCESS_MESSAGE: &str = "Successfully logged in";
 38→
 39→/// Installs a small file-backed tracing layer for direct `codex login` flows.
 40→///
 41→/// This deliberately duplicates a narrow slice of the TUI logging setup instead of reusing it
 42→/// wholesale. The TUI stack includes session-oriented layers that are valuable for interactive
 43→/// runs but unnecessary for a one-shot login command. Keeping the direct CLI path local lets this
 44→/// command produce a durable `codex-login.log` artifact without coupling it to the TUI's broader
 45→/// telemetry and feedback initialization.
 46→fn init_login_file_logging(config: &Config) -> Option<WorkerGuard> {
 47→    let log_dir = match codex_core::config::log_dir(config) {
 48→        Ok(log_dir) => log_dir,
 49→        Err(err) => {
 50→            eprintln!("Warning: failed to resolve login log directory: {err}");
 51→            return None;
 52→        }
 53→    };
 54→
 55→    if let Err(err) = std::fs::create_dir_all(&log_dir) {
 56→        eprintln!(
 57→            "Warning: failed to create login log directory {}: {err}",
 58→            log_dir.display()
 59→        );
 60→        return None;
 61→    }
 62→
 63→    let mut log_file_opts = OpenOptions::new();
 64→    log_file_opts.create(true).append(true);
 65→
 66→    #[cfg(unix)]
 67→    {
 68→        use std::os::unix::fs::OpenOptionsExt;
 69→        log_file_opts.mode(0o600);
 70→    }
 71→
 72→    let log_path = log_dir.join("codex-login.log");
 73→    let log_file = match log_file_opts.open(&log_path) {
 74→        Ok(log_file) => log_file,
 75→        Err(err) => {
 76→            eprintln!(
 77→                "Warning: failed to open login log file {}: {err}",
 78→                log_path.display()
 79→            );
 80→            return None;
 81→        }
 82→    };
 83→
 84→    let (non_blocking, guard) = non_blocking(log_file);
 85→    let env_filter = EnvFilter::try_from_default_env()
 86→        .unwrap_or_else(|_| EnvFilter::new("codex_cli=info,codex_core=info,codex_login=info"));
 87→    let file_layer = tracing_subscriber::fmt::layer()
 88→        .with_writer(non_blocking)
 89→        .with_target(true)
 90→        .with_ansi(false)
 91→        .with_filter(env_filter);
 92→
 93→    // Direct `codex login` otherwise relies on ephemeral stderr and browser output.
 94→    // Persist the same login targets to a file so support can inspect auth failures
 95→    // without reproducing them through TUI or app-server.
 96→    if let Err(err) = tracing_subscriber::registry().with(file_layer).try_init() {
 97→        eprintln!(
 98→            "Warning: failed to initialize login log file {}: {err}",
 99→            log_path.display()
100→        );
101→        return None;
102→    }
103→
104→    Some(guard)
105→}
