 1→//! Entry-point for the `codex-exec` binary.
 2→//!
 3→//! When this CLI is invoked normally, it parses the standard `codex-exec` CLI
 4→//! options and launches the non-interactive Codex agent. However, if it is
 5→//! invoked with arg0 as `codex-linux-sandbox`, we instead treat the invocation
 6→//! as a request to run the logic for the standalone `codex-linux-sandbox`
 7→//! executable (i.e., parse any -s args and then run a *sandboxed* command under
 8→//! Landlock + seccomp.
 9→//!
10→//! This allows us to ship a completely separate set of functionality as part
11→//! of the `codex-exec` binary.
12→use clap::Parser;
13→use codex_arg0::Arg0DispatchPaths;
14→use codex_arg0::arg0_dispatch_or_else;
15→use codex_exec::Cli;
16→use codex_exec::run_main;
17→use codex_utils_cli::CliConfigOverrides;
18→
19→#[derive(Parser, Debug)]
20→struct TopCli {
21→    #[clap(flatten)]
22→    config_overrides: CliConfigOverrides,
23→
24→    #[clap(flatten)]
25→    inner: Cli,
26→}
27→
28→fn main() -> anyhow::Result<()> {
29→    arg0_dispatch_or_else(|arg0_paths: Arg0DispatchPaths| async move {
30→        let top_cli = TopCli::parse();
31→        // Merge root-level overrides into inner CLI struct so downstream logic remains unchanged.
32→        let mut inner = top_cli.inner;
33→        inner
34→            .config_overrides
35→            .raw_overrides
36→            .splice(0..0, top_cli.config_overrides.raw_overrides);
37→
38→        run_main(inner, arg0_paths).await?;
39→        Ok(())
40→    })
41→}
42→
43→#[cfg(test)]
44→mod tests {
45→    use super::*;
46→    use pretty_assertions::assert_eq;
47→
48→    #[test]
49→    fn top_cli_parses_resume_prompt_after_config_flag() {
50→        const PROMPT: &str = "echo resume-with-global-flags-after-subcommand";
51→        let cli = TopCli::parse_from([
52→            "codex-exec",
53→            "resume",
54→            "--last",
55→            "--json",
56→            "--model",
57→            "gpt-5.2-codex",
58→            "--config",
59→            "reasoning_level=xhigh",
60→            "--dangerously-bypass-approvals-and-sandbox",
61→            "--skip-git-repo-check",
62→            PROMPT,
63→        ]);
64→
65→        let Some(codex_exec::Command::Resume(args)) = cli.inner.command else {
66→            panic!("expected resume command");
67→        };
68→        let effective_prompt = args.prompt.clone().or_else(|| {
69→            if args.last {
70→                args.session_id.clone()
71→            } else {
72→                None
73→            }
74→        });
75→        assert_eq!(effective_prompt.as_deref(), Some(PROMPT));
76→        assert_eq!(cli.config_overrides.raw_overrides.len(), 1);
77→        assert_eq!(
78→            cli.config_overrides.raw_overrides[0],
79→            "reasoning_level=xhigh"
80→        );
81→    }
82→}
