168→pub(crate) async fn inspect_pending_input(
169→    sess: &Arc<Session>,
170→    turn_context: &Arc<TurnContext>,
171→    pending_input_item: ResponseInputItem,
172→) -> PendingInputHookDisposition {
173→    let response_item = ResponseItem::from(pending_input_item);
174→    if let Some(TurnItem::UserMessage(user_message)) = parse_turn_item(&response_item) {
175→        let user_prompt_submit_outcome =
176→            run_user_prompt_submit_hooks(sess, turn_context, user_message.message()).await;
177→        if user_prompt_submit_outcome.should_stop {
178→            PendingInputHookDisposition::Blocked {
179→                additional_contexts: user_prompt_submit_outcome.additional_contexts,
180→            }
181→        } else {
182→            PendingInputHookDisposition::Accepted(Box::new(PendingInputRecord::UserMessage {
183→                content: user_message.content,
184→                response_item,
185→                additional_contexts: user_prompt_submit_outcome.additional_contexts,
186→            }))
187→        }
188→    } else {
189→        PendingInputHookDisposition::Accepted(Box::new(PendingInputRecord::ConversationItem {
190→            response_item,
191→        }))
192→    }
193→}
