 83→/// To build up the set of admin-enforced constraints, we build up from multiple
 84→/// configuration layers in the following order, but a constraint defined in an
 85→/// earlier layer cannot be overridden by a later layer:
 86→///
 87→/// - cloud:    managed cloud requirements
 88→/// - admin:    managed preferences (*)
 89→/// - system    `/etc/codex/requirements.toml` (Unix) or
 90→///   `%ProgramData%\OpenAI\Codex\requirements.toml` (Windows)
 91→///
 92→/// For backwards compatibility, we also load from
 93→/// `managed_config.toml` and map it to `requirements.toml`.
 94→///
 95→/// Configuration is built up from multiple layers in the following order:
 96→///
 97→/// - admin:    managed preferences (*)
 98→/// - system    `/etc/codex/config.toml` (Unix) or
 99→///   `%ProgramData%\OpenAI\Codex\config.toml` (Windows)
100→/// - user      `${CODEX_HOME}/config.toml`
101→/// - cwd       `${PWD}/config.toml` (loaded but disabled when the directory is untrusted)
102→/// - tree      parent directories up to root looking for `./.codex/config.toml` (loaded but disabled when untrusted)
103→/// - repo      `$(git rev-parse --show-toplevel)/.codex/config.toml` (loaded but disabled when untrusted)
104→/// - runtime   e.g., --config flags, model selector in UI
105→///
106→/// (*) Only available on macOS via managed device profiles.
107→///
108→/// See https://developers.openai.com/codex/security for details.
109→///
110→/// When loading the config stack for a thread, there should be a `cwd`
111→/// associated with it such that `cwd` should be `Some(...)`. Only for
112→/// thread-agnostic config loading (e.g., for the app server's `/config`
113→/// endpoint) should `cwd` be `None`.
114→pub async fn load_config_layers_state(
115→    codex_home: &Path,
116→    cwd: Option<AbsolutePathBuf>,
117→    cli_overrides: &[(String, TomlValue)],
118→    overrides: LoaderOverrides,
119→    cloud_requirements: CloudRequirementsLoader,
120→) -> io::Result<ConfigLayerStack> {
121→    let mut config_requirements_toml = ConfigRequirementsWithSources::default();
122→
123→    if let Some(requirements) = cloud_requirements.get().await.map_err(io::Error::other)? {
124→        config_requirements_toml
125→            .merge_unset_fields(RequirementSource::CloudRequirements, requirements);
126→    }
127→
128→    #[cfg(target_os = "macos")]
129→    macos::load_managed_admin_requirements_toml(
130→        &mut config_requirements_toml,
131→        overrides
132→            .macos_managed_config_requirements_base64
133→            .as_deref(),
134→    )
135→    .await?;
136→
137→    // Honor the system requirements.toml location.
138→    let requirements_toml_file = system_requirements_toml_file()?;
139→    load_requirements_toml(&mut config_requirements_toml, requirements_toml_file).await?;
140→
141→    // Make a best-effort to support the legacy `managed_config.toml` as a
142→    // requirements specification.
143→    let loaded_config_layers = layer_io::load_config_layers_internal(codex_home, overrides).await?;
144→    load_requirements_from_legacy_scheme(
145→        &mut config_requirements_toml,
146→        loaded_config_layers.clone(),
147→    )
148→    .await?;
149→
150→    let mut layers = Vec::<ConfigLayerEntry>::new();
151→
152→    let cli_overrides_layer = if cli_overrides.is_empty() {
153→        None
154→    } else {
155→        let cli_overrides_layer = build_cli_overrides_layer(cli_overrides);
156→        let base_dir = cwd
157→            .as_ref()
158→            .map(AbsolutePathBuf::as_path)
159→            .unwrap_or(codex_home);
160→        Some(resolve_relative_paths_in_config_toml(
161→            cli_overrides_layer,
162→            base_dir,
163→        )?)
164→    };
165→
166→    // Include an entry for the "system" config folder, loading its config.toml,
167→    // if it exists.
168→    let system_config_toml_file = system_config_toml_file()?;
169→    let system_layer =
170→        load_config_toml_for_required_layer(&system_config_toml_file, |config_toml| {
171→            ConfigLayerEntry::new(
172→                ConfigLayerSource::System {
173→                    file: system_config_toml_file.clone(),
174→                },
175→                config_toml,
176→            )
177→        })
178→        .await?;
179→    layers.push(system_layer);
180→
181→    // Add a layer for $CODEX_HOME/config.toml if it exists. Note if the file
182→    // exists, but is malformed, then this error should be propagated to the
183→    // user.
184→    let user_file = AbsolutePathBuf::resolve_path_against_base(CONFIG_TOML_FILE, codex_home)?;
185→    let user_layer = load_config_toml_for_required_layer(&user_file, |config_toml| {
186→        ConfigLayerEntry::new(
187→            ConfigLayerSource::User {
188→                file: user_file.clone(),
189→            },
190→            config_toml,
191→        )
192→    })
193→    .await?;
194→    layers.push(user_layer);
195→
196→    if let Some(cwd) = cwd {
197→        let mut merged_so_far = TomlValue::Table(toml::map::Map::new());
198→        for layer in &layers {
199→            merge_toml_values(&mut merged_so_far, &layer.config);
200→        }

200→        }
201→        if let Some(cli_overrides_layer) = cli_overrides_layer.as_ref() {
202→            merge_toml_values(&mut merged_so_far, cli_overrides_layer);
203→        }
204→
205→        let project_root_markers = match project_root_markers_from_config(&merged_so_far) {
206→            Ok(markers) => markers.unwrap_or_else(default_project_root_markers),
207→            Err(err) => {
208→                if let Some(config_error) = first_layer_config_error_from_entries(&layers).await {
209→                    return Err(io_error_from_config_error(
210→                        io::ErrorKind::InvalidData,
211→                        config_error,
212→                        /*source*/ None,
213→                    ));
214→                }
215→                return Err(err);
216→            }
217→        };
218→        let project_trust_context = match project_trust_context(
219→            &merged_so_far,
220→            &cwd,
221→            &project_root_markers,
222→            codex_home,
223→            &user_file,
224→        )
225→        .await
226→        {
227→            Ok(context) => context,
228→            Err(err) => {
229→                let source = err
230→                    .get_ref()
231→                    .and_then(|err| err.downcast_ref::<toml::de::Error>())
232→                    .cloned();
233→                if let Some(config_error) = first_layer_config_error_from_entries(&layers).await {
234→                    return Err(io_error_from_config_error(
235→                        io::ErrorKind::InvalidData,
236→                        config_error,
237→                        source,
238→                    ));
239→                }
240→                return Err(err);
241→            }
242→        };
243→        let project_layers = load_project_layers(
244→            &cwd,
245→            &project_trust_context.project_root,
246→            &project_trust_context,
247→            codex_home,
248→        )
249→        .await?;
250→        layers.extend(project_layers);
251→    }
252→
253→    // Add a layer for runtime overrides from the CLI or UI, if any exist.
254→    if let Some(cli_overrides_layer) = cli_overrides_layer {
255→        layers.push(ConfigLayerEntry::new(
256→            ConfigLayerSource::SessionFlags,
257→            cli_overrides_layer,
258→        ));
259→    }
260→
261→    // Make a best-effort to support the legacy `managed_config.toml` as a
262→    // config layer on top of everything else. For fields in
263→    // `managed_config.toml` that do not have an equivalent in
264→    // `ConfigRequirements`, note users can still override these values on a
265→    // per-turn basis in the TUI and VS Code.
266→    let LoadedConfigLayers {
267→        managed_config,
268→        managed_config_from_mdm,
269→    } = loaded_config_layers;
270→    if let Some(config) = managed_config {
271→        let managed_parent = config.file.as_path().parent().ok_or_else(|| {
272→            io::Error::new(
273→                io::ErrorKind::InvalidData,
274→                format!(
275→                    "Managed config file {} has no parent directory",
276→                    config.file.as_path().display()
277→                ),
278→            )
279→        })?;
280→        let managed_config =
281→            resolve_relative_paths_in_config_toml(config.managed_config, managed_parent)?;
282→        layers.push(ConfigLayerEntry::new(
283→            ConfigLayerSource::LegacyManagedConfigTomlFromFile { file: config.file },
284→            managed_config,
285→        ));
286→    }
287→    if let Some(config) = managed_config_from_mdm {
288→        let managed_config =
289→            resolve_relative_paths_in_config_toml(config.managed_config, codex_home)?;
290→        layers.push(ConfigLayerEntry::new_with_raw_toml(
291→            ConfigLayerSource::LegacyManagedConfigTomlFromMdm,
292→            managed_config,
293→            config.raw_toml,
294→        ));
295→    }
296→
297→    ConfigLayerStack::new(
298→        layers,
299→        config_requirements_toml.clone().try_into()?,
300→        config_requirements_toml.into_toml(),
301→    )
302→}
