304→/// Attempts to load a config.toml file from `config_toml`.
305→/// - If the file exists and is valid TOML, passes the parsed `toml::Value` to
306→///   `create_entry` and returns the resulting layer entry.
307→/// - If the file does not exist, uses an empty `Table` with `create_entry` and
308→///   returns the resulting layer entry.
309→/// - If there is an error reading the file or parsing the TOML, returns an
310→///   error.
311→async fn load_config_toml_for_required_layer(
312→    config_toml: impl AsRef<Path>,
313→    create_entry: impl FnOnce(TomlValue) -> ConfigLayerEntry,
314→) -> io::Result<ConfigLayerEntry> {
315→    let toml_file = config_toml.as_ref();
316→    let toml_value = match tokio::fs::read_to_string(toml_file).await {
317→        Ok(contents) => {
318→            let config: TomlValue = toml::from_str(&contents).map_err(|err| {
319→                let config_error = config_error_from_toml(toml_file, &contents, err.clone());
320→                io_error_from_config_error(io::ErrorKind::InvalidData, config_error, Some(err))
321→            })?;
322→            let config_parent = toml_file.parent().ok_or_else(|| {
323→                io::Error::new(
324→                    io::ErrorKind::InvalidData,
325→                    format!(
326→                        "Config file {} has no parent directory",
327→                        toml_file.display()
328→                    ),
329→                )
330→            })?;
331→            resolve_relative_paths_in_config_toml(config, config_parent)
332→        }
333→        Err(e) => {
334→            if e.kind() == io::ErrorKind::NotFound {
335→                Ok(TomlValue::Table(toml::map::Map::new()))
336→            } else {
337→                Err(io::Error::new(
338→                    e.kind(),
339→                    format!("Failed to read config file {}: {e}", toml_file.display()),
340→                ))
341→            }
342→        }
343→    }?;
344→
345→    Ok(create_entry(toml_value))
346→}
