348→/// If available, apply requirements from the platform system
349→/// `requirements.toml` location to `config_requirements_toml` by filling in
350→/// any unset fields.
351→async fn load_requirements_toml(
352→    config_requirements_toml: &mut ConfigRequirementsWithSources,
353→    requirements_toml_file: impl AsRef<Path>,
354→) -> io::Result<()> {
355→    let requirements_toml_file =
356→        AbsolutePathBuf::from_absolute_path(requirements_toml_file.as_ref())?;
357→    match tokio::fs::read_to_string(&requirements_toml_file).await {
358→        Ok(contents) => {
359→            let requirements_config: ConfigRequirementsToml =
360→                toml::from_str(&contents).map_err(|e| {
361→                    io::Error::new(
362→                        io::ErrorKind::InvalidData,
363→                        format!(
364→                            "Error parsing requirements file {}: {e}",
365→                            requirements_toml_file.as_ref().display(),
366→                        ),
367→                    )
368→                })?;
369→            config_requirements_toml.merge_unset_fields(
370→                RequirementSource::SystemRequirementsToml {
371→                    file: requirements_toml_file.clone(),
372→                },
373→                requirements_config,
374→            );
375→        }
376→        Err(e) => {
377→            if e.kind() != io::ErrorKind::NotFound {
378→                return Err(io::Error::new(
379→                    e.kind(),
380→                    format!(
381→                        "Failed to read requirements file {}: {e}",
382→                        requirements_toml_file.as_ref().display(),
383→                    ),
384→                ));
385→            }
386→        }
387→    }
388→
389→    Ok(())
390→}
