436→#[cfg(windows)]
437→fn windows_program_data_dir_from_known_folder() -> io::Result<PathBuf> {
438→    use std::ffi::OsString;
439→    use std::os::windows::ffi::OsStringExt;
440→    use windows_sys::Win32::System::Com::CoTaskMemFree;
441→    use windows_sys::Win32::UI::Shell::FOLDERID_ProgramData;
442→    use windows_sys::Win32::UI::Shell::KF_FLAG_DEFAULT;
443→    use windows_sys::Win32::UI::Shell::SHGetKnownFolderPath;
444→
445→    let mut path_ptr = std::ptr::null_mut::<u16>();
446→    let known_folder_flags = u32::try_from(KF_FLAG_DEFAULT).map_err(|_| {
447→        io::Error::other(format!(
448→            "KF_FLAG_DEFAULT did not fit in u32: {KF_FLAG_DEFAULT}"
449→        ))
450→    })?;
451→    // Known folder IDs reference:
452→    // https://learn.microsoft.com/en-us/windows/win32/shell/knownfolderid
453→    // SAFETY: SHGetKnownFolderPath initializes path_ptr with a CoTaskMem-allocated,
454→    // null-terminated UTF-16 string on success.
455→    let hr = unsafe {
456→        SHGetKnownFolderPath(&FOLDERID_ProgramData, known_folder_flags, 0, &mut path_ptr)
457→    };
458→    if hr != 0 {
459→        return Err(io::Error::other(format!(
460→            "SHGetKnownFolderPath(FOLDERID_ProgramData) failed with HRESULT {hr:#010x}"
461→        )));
462→    }
463→    if path_ptr.is_null() {
464→        return Err(io::Error::other(
465→            "SHGetKnownFolderPath(FOLDERID_ProgramData) returned a null pointer",
466→        ));
467→    }
468→
469→    // SAFETY: path_ptr is a valid null-terminated UTF-16 string allocated by
470→    // SHGetKnownFolderPath and must be freed with CoTaskMemFree.
471→    let path = unsafe {
472→        let mut len = 0usize;
473→        while *path_ptr.add(len) != 0 {
474→            len += 1;
475→        }
476→        let wide = std::slice::from_raw_parts(path_ptr, len);
477→        let path = PathBuf::from(OsString::from_wide(wide));
478→        CoTaskMemFree(path_ptr.cast());
479→        path
480→    };
481→
482→    Ok(path)
483→}
