873→            }
874→            Err(err) => {
875→                if err.kind() == io::ErrorKind::NotFound {
876→                    // If there is no config.toml file, record an empty entry
877→                    // for this project layer, as this may still have subfolders
878→                    // that are significant in the overall ConfigLayerStack.
879→                    layers.push(project_layer_entry(
880→                        trust_context,
881→                        &dot_codex_abs,
882→                        &layer_dir,
883→                        TomlValue::Table(toml::map::Map::new()),
884→                        /*config_toml_exists*/ false,
885→                    ));
886→                } else {
887→                    let config_file_display = config_file.as_path().display();
888→                    return Err(io::Error::new(
889→                        err.kind(),
890→                        format!("Failed to read project config file {config_file_display}: {err}"),
891→                    ));
892→                }
893→            }
894→        }
895→    }
896→
897→    Ok(layers)
