 13→pub(crate) struct DiscoveryResult {
 14→    pub handlers: Vec<ConfiguredHandler>,
 15→    pub warnings: Vec<String>,
 16→}
 17→
 18→pub(crate) fn discover_handlers(config_layer_stack: Option<&ConfigLayerStack>) -> DiscoveryResult {
 19→    let Some(config_layer_stack) = config_layer_stack else {
 20→        return DiscoveryResult {
 21→            handlers: Vec::new(),
 22→            warnings: Vec::new(),
 23→        };
 24→    };
 25→
 26→    let mut handlers = Vec::new();
 27→    let mut warnings = Vec::new();
 28→    let mut display_order = 0_i64;
 29→
 30→    for layer in config_layer_stack.get_layers(
 31→        ConfigLayerStackOrdering::LowestPrecedenceFirst,
 32→        /*include_disabled*/ false,
 33→    ) {
 34→        let Some(folder) = layer.config_folder() else {
 35→            continue;
 36→        };
 37→        let source_path = match folder.join("hooks.json") {
 38→            Ok(source_path) => source_path,
 39→            Err(err) => {
 40→                warnings.push(format!(
 41→                    "failed to resolve hooks config path from {}: {err}",
 42→                    folder.display()
 43→                ));
 44→                continue;
 45→            }
 46→        };
 47→        if !source_path.as_path().is_file() {
 48→            continue;
 49→        }
 50→
 51→        let contents = match fs::read_to_string(source_path.as_path()) {
 52→            Ok(contents) => contents,
 53→            Err(err) => {
 54→                warnings.push(format!(
 55→                    "failed to read hooks config {}: {err}",
 56→                    source_path.display()
 57→                ));
 58→                continue;
 59→            }
 60→        };
 61→
 62→        let parsed: HooksFile = match serde_json::from_str(&contents) {
 63→            Ok(parsed) => parsed,
 64→            Err(err) => {
 65→                warnings.push(format!(
 66→                    "failed to parse hooks config {}: {err}",
 67→                    source_path.display()
 68→                ));
 69→                continue;
 70→            }
 71→        };
 72→
 73→        for group in parsed.hooks.pre_tool_use {
 74→            append_group_handlers(
 75→                &mut handlers,
 76→                &mut warnings,
 77→                &mut display_order,
 78→                source_path.as_path(),
 79→                codex_protocol::protocol::HookEventName::PreToolUse,
 80→                matcher_pattern_for_event(
 81→                    codex_protocol::protocol::HookEventName::PreToolUse,
 82→                    group.matcher.as_deref(),
 83→                ),
 84→                group.hooks,
 85→            );
 86→        }
 87→
 88→        for group in parsed.hooks.session_start {
 89→            append_group_handlers(
 90→                &mut handlers,
 91→                &mut warnings,
 92→                &mut display_order,
 93→                source_path.as_path(),
 94→                codex_protocol::protocol::HookEventName::SessionStart,
 95→                matcher_pattern_for_event(
 96→                    codex_protocol::protocol::HookEventName::SessionStart,
 97→                    group.matcher.as_deref(),
 98→                ),
 99→                group.hooks,
100→            );
101→        }
102→
103→        for group in parsed.hooks.user_prompt_submit {
104→            append_group_handlers(
105→                &mut handlers,
106→                &mut warnings,
107→                &mut display_order,
108→                source_path.as_path(),
109→                codex_protocol::protocol::HookEventName::UserPromptSubmit,
110→                matcher_pattern_for_event(
111→                    codex_protocol::protocol::HookEventName::UserPromptSubmit,
112→                    group.matcher.as_deref(),
113→                ),
114→                group.hooks,
115→            );
116→        }
117→
118→        for group in parsed.hooks.stop {
119→            append_group_handlers(
120→                &mut handlers,
121→                &mut warnings,
122→                &mut display_order,
123→                source_path.as_path(),
124→                codex_protocol::protocol::HookEventName::Stop,
125→                matcher_pattern_for_event(
126→                    codex_protocol::protocol::HookEventName::Stop,
127→                    group.matcher.as_deref(),
128→                ),
129→                group.hooks,
130→            );
131→        }
132→    }
133→
134→    DiscoveryResult { handlers, warnings }
135→}
136→
137→fn append_group_handlers(
138→    handlers: &mut Vec<ConfiguredHandler>,
139→    warnings: &mut Vec<String>,
140→    display_order: &mut i64,
141→    source_path: &Path,
142→    event_name: codex_protocol::protocol::HookEventName,
143→    matcher: Option<&str>,
144→    group_handlers: Vec<HookHandlerConfig>,
145→) {
146→    if let Some(matcher) = matcher
147→        && let Err(err) = validate_matcher_pattern(matcher)
148→    {
149→        warnings.push(format!(
150→            "invalid matcher {matcher:?} in {}: {err}",
151→            source_path.display()
152→        ));
153→        return;
154→    }
155→
156→    for handler in group_handlers {
157→        match handler {
158→            HookHandlerConfig::Command {
159→                command,
160→                timeout_sec,
161→                r#async,
162→                status_message,
163→            } => {
164→                if r#async {
165→                    warnings.push(format!(
166→                        "skipping async hook in {}: async hooks are not supported yet",
167→                        source_path.display()
168→                    ));
169→                    continue;
170→                }
171→                if command.trim().is_empty() {
172→                    warnings.push(format!(
173→                        "skipping empty hook command in {}",
174→                        source_path.display()
175→                    ));
176→                    continue;
177→                }
178→                let timeout_sec = timeout_sec.unwrap_or(600).max(1);
179→                handlers.push(ConfiguredHandler {
180→                    event_name,
181→                    matcher: matcher.map(ToOwned::to_owned),
182→                    command,
183→                    timeout_sec,
184→                    status_message,
185→                    source_path: source_path.to_path_buf(),
186→                    display_order: *display_order,
187→                });
188→                *display_order += 1;
189→            }
190→            HookHandlerConfig::Prompt {} => warnings.push(format!(
191→                "skipping prompt hook in {}: prompt hooks are not supported yet",
192→                source_path.display()
193→            )),
194→            HookHandlerConfig::Agent {} => warnings.push(format!(
195→                "skipping agent hook in {}: agent hooks are not supported yet",
196→                source_path.display()
197→            )),
198→        }
199→    }
200→}

