710→/// Takes a `toml::Value` parsed from a config.toml file and walks through it,
711→/// resolving any `AbsolutePathBuf` fields against `base_dir`, returning a new
712→/// `toml::Value` with the same shape but with paths resolved.
713→///
714→/// This ensures that multiple config layers can be merged together correctly
715→/// even if they were loaded from different directories.
716→pub(crate) fn resolve_relative_paths_in_config_toml(
717→    value_from_config_toml: TomlValue,
718→    base_dir: &Path,
719→) -> io::Result<TomlValue> {
720→    // Use the serialize/deserialize round-trip to convert the
721→    // `toml::Value` into a `ConfigToml` with `AbsolutePath
722→    let _guard = AbsolutePathBufGuard::new(base_dir);
723→    let Ok(resolved) = value_from_config_toml.clone().try_into::<ConfigToml>() else {
724→        return Ok(value_from_config_toml);
725→    };
726→    drop(_guard);
727→
728→    let resolved_value = TomlValue::try_from(resolved).map_err(|e| {
729→        io::Error::new(
730→            io::ErrorKind::InvalidData,
731→            format!("Failed to serialize resolved config: {e}"),
732→        )
733→    })?;
734→
735→    Ok(copy_shape_from_original(
736→        &value_from_config_toml,
737→        &resolved_value,
738→    ))
739→}
740→
741→/// Ensure that every field in `original` is present in the returned
742→/// `toml::Value`, taking the value from `resolved` where possible. This ensures
743→/// the fields that we "removed" during the serialize/deserialize round-trip in
744→/// `resolve_config_paths` are preserved, out of an abundance of caution.
745→fn copy_shape_from_original(original: &TomlValue, resolved: &TomlValue) -> TomlValue {
746→    match (original, resolved) {
747→        (TomlValue::Table(original_table), TomlValue::Table(resolved_table)) => {
748→            let mut table = toml::map::Map::new();
749→            for (key, original_value) in original_table {
750→                let resolved_value = resolved_table.get(key).unwrap_or(original_value);
751→                table.insert(
752→                    key.clone(),
753→                    copy_shape_from_original(original_value, resolved_value),
754→                );
755→            }
756→            TomlValue::Table(table)
757→        }
758→        (TomlValue::Array(original_array), TomlValue::Array(resolved_array)) => {
759→            let mut items = Vec::new();
760→            for (index, original_value) in original_array.iter().enumerate() {
761→                let resolved_value = resolved_array.get(index).unwrap_or(original_value);
762→                items.push(copy_shape_from_original(original_value, resolved_value));
763→            }
764→            TomlValue::Array(items)
765→        }
766→        (_, resolved_value) => resolved_value.clone(),
767→    }
768→}
